<!--
  任务进度条 (历史记录与工作台队列共用)。

  服务端在推理过程中**不提供任何进度**, 因此进度只能是"已用时间 / 预估时间", 预估由
  `estimator` 按**采样步数分桶**并用实测样本校准 (`voice/estimate.ts`)。据此: 进度条走
  到头不等于完成 (偏慢的任务会停在 100% 等结果); 排队中的任务还没有开始时间, 只显示"预计"。

  秒级定时器只在**任务真的在跑**时启动, 没有活动任务时不该每秒重渲染。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import { estimator, formatDuration, formatEta } from '../voice/estimate';

  let {
    /** 这次生成用的采样步数 (预估按它分桶) */
    steps,
    /** 任务文本 (估算按字符数) */
    text,
    /** 开始推理的时刻; 未开始 (排队中) 时省略 */
    startedAt,
  }: {
    steps: number;
    text: string;
    startedAt?: number;
  } = $props();

  // 只读 `startedAt`、写 `now` 用赋值 (Svelte 只把读取记成依赖), 因此不会自激
  let now = $state(Date.now());
  $effect(() => {
    if (startedAt === undefined) return;
    now = Date.now();
    const timer = setInterval(() => (now = Date.now()), 1000);
    return () => clearInterval(timer);
  });

  const total = $derived(estimator.estimate(steps, text.length));
  const elapsed = $derived(startedAt === undefined ? 0 : Math.max(0, now - startedAt));
  const remaining = $derived(total - elapsed);
  const ratio = $derived(total > 0 ? Math.min(1, elapsed / total) : 0);
</script>

{#if startedAt === undefined}
  <div class="task-progress">
    <span class="task-progress-text">预计 {formatEta(total)}</span>
  </div>
{:else}
  <div class="task-progress">
    <div class="task-progress-bar">
      <div class="task-progress-fill" style="width:{ratio * 100}%"></div>
    </div>
    <span class="task-progress-text">
      已用 {formatDuration(elapsed)} · {remaining > 0 ? `预计还需 ${formatEta(remaining)}` : '仍在推理…'}
    </span>
  </div>
{/if}
